  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$‘ਹੰਕਾਰ’ ਸ਼ਬਦ ਦੇ ਸ਼ਾਬਦਿਕ ਅਰਥ, ਉਤਪਤੀ ਅਤੇ ਸਮਾਨਾਰਥੀ ਸ਼ਬਦਾਂ ਦੀ ਵਿਆਖਿਆ ਕਰੋ। ਹੰਕਾਰੀ ਵਿਅਕਤੀ ਦੇ ਸੁਭਾਅ ਅਤੇ ਉਸਦੇ ਨਤੀਜਿਆਂ ਬਾਰੇ ਵਿਸਥਾਰਪੂਰਵਕ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਧਾਰਮਿਕ ਗ੍ਰੰਥਾਂ ਅਤੇ ਗੁਰਬਾਣੀ ਵਿੱਚ ਹੰਕਾਰ ਬਾਰੇ ਕੀ ਸਿੱਖਿਆ ਦਿੱਤੀ ਗਈ ਹੈ? ਗੁਰਬਾਣੀ ਦੀ ਤੁਕ “ਧਨ ਭੂਮਿ ਕਾ ਜੋ ਕਰੈ ਗੁਮਾਨੁ॥ ਸੋ ਮੂਰਖੁ ਅੰਧਾ ਅਗਿਆਨੁ॥” ਦੇ ਸੰਦਰਭ ਵਿੱਚ ਇਸਦੀ ਮਹੱਤਤਾ ਸਪੱਸ਼ਟ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਨੁੱਖੀ ਜੀਵਨ ਵਿੱਚ ਗੁਣਾਂ ਅਤੇ ਅਵਗੁਣਾਂ ਦੀ ਭੂਮਿਕਾ ਦਾ ਵਿਸ਼ਲੇਸ਼ਣ ਕਰੋ। ਇਹਨਾਂ ਵਿੱਚੋਂ ਹੰਕਾਰ ਅਤੇ ਸਵੈਮਾਨ ਨੂੰ ਵਿਸ਼ੇਸ਼ ਮਹੱਤਵ ਕਿਉਂ ਦਿੱਤਾ ਗਿਆ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲੇਖਕ ਦਾ ਮਨੁੱਖੀ ਸੁਭਾਅ ਬਾਰੇ ਕੀ ਦ੍ਰਿਸ਼ਟੀਕੋਣ ਹੈ? ਪਾਠ ਦੇ ਆਧਾਰ 'ਤੇ ਦੱਸੋ ਕਿ ਮਨੁੱਖ ਨੂੰ ਸਿੱਧੇ ਰਸਤੇ 'ਤੇ ਚੱਲਣ ਲਈ ਕਿਹੜੀਆਂ ਭਾਵਨਾਵਾਂ ਅਪਣਾਉਣੀਆਂ ਚਾਹੀਦੀਆਂ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੰਕਾਰ ਦੇ ਵੱਖ-ਵੱਖ ਰੂਪਾਂ (ਤਾਕਤ, ਧਨ-ਦੌਲਤ, ਗਿਆਨ, ਰੂਪ, ਯੋਗਤਾ ਜਾਂ ਪਦਵੀ ਦਾ ਹੰਕਾਰ) ਦੀ ਵਿਆਖਿਆ ਕਰੋ ਅਤੇ ਦੱਸੋ ਕਿ ਇਹ ਮਨੁੱਖ ਨੂੰ ਕਿਵੇਂ ਭਟਕਾਉਂਦੇ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਵੈਮਾਨ ਨੂੰ ਮਨੁੱਖੀ ਜੀਵਨ ਦੀ ਉੱਨਤੀ ਲਈ ਕਿਉਂ ਜ਼ਰੂਰੀ ਮੰਨਿਆ ਜਾਂਦਾ ਹੈ? ਇਸਦੇ ਸਕਾਰਾਤਮਕ ਪ੍ਰਭਾਵਾਂ ਬਾਰੇ ਵਿਸਥਾਰ ਨਾਲ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੰਕਾਰ ਤੋਂ ਮੁਕਤੀ ਪਾਉਣ ਲਈ ਪਾਠ ਵਿੱਚ ਕਿਹੜੇ ਉਪਾਅ ਸੁਝਾਏ ਗਏ ਹਨ? ਪਰਉਪਕਾਰ ਦੀ ਭਾਵਨਾ ਦੀ ਮਹੱਤਤਾ ਨੂੰ ਉਜਾਗਰ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਨੁੱਖੀ ਜੀਵਨ ਦੀ ਵਿਲੱਖਣਤਾ ਤੋਂ ਕੀ ਭਾਵ ਹੈ? ਇਸ ਵਿੱਚ ਚਾਨਣ ਦੇ ਚਮਕਾਰੇ ਅਤੇ ਹਨੇਰੇ ਦੇ ਸਾਏ ਕਿਵੇਂ ਮੌਜੂਦ ਹੁੰਦੇ ਹਨ, ਵਿਸਥਾਰ ਸਹਿਤ ਦੱਸੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਦਿੱਤੇ ਗਏ ਔਖੇ ਸ਼ਬਦਾਂ (ਵਿਲੱਖਣ, ਪਤਨ, ਬੁਲੰਦੀਆਂ, ਵਿਕਾਰ, ਸ਼ੁਮਾਰ) ਦੇ ਅਰਥਾਂ ਦੀ ਵਿਆਖਿਆ ਕਰੋ ਅਤੇ ਇਹਨਾਂ ਦੀ ਪਾਠ ਵਿੱਚ ਵਰਤੋਂ ਦੇ ਮਹੱਤਵ ਨੂੰ ਦੱਸੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੰਕਾਰ ਅਤੇ ਸਵੈਮਾਨ ਦੇ ਸੰਕਲਪਾਂ ਨੂੰ ਸਮਕਾਲੀ ਸਮਾਜ ਵਿੱਚ ਕਿਵੇਂ ਦੇਖਿਆ ਜਾ ਸਕਦਾ ਹੈ? ਇਹਨਾਂ ਦੇ ਪ੍ਰਭਾਵਾਂ ਦੀ ਤੁਲਨਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਗੁਰਬਾਣੀ ਅਨੁਸਾਰ ਮਨੁੱਖੀ ਸੁਭਾਅ ਦੇ ਪੰਜ ਮੁੱਖ ਵਿਕਾਰ ਕਿਹੜੇ ਹਨ ਅਤੇ ਹੰਕਾਰ ਇਹਨਾਂ ਵਿੱਚੋਂ ਇੱਕ ਕਿਵੇਂ ਹੈ? ਵਿਸਥਾਰ ਨਾਲ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੰਕਾਰੀ ਵਿਅਕਤੀ ਸਮਾਜ ਵਿੱਚ ਕਿਹੋ ਜਿਹੀ ਸਥਿਤੀ ਦਾ ਸਾਹਮਣਾ ਕਰਦਾ ਹੈ? ਉਸਦੇ ਸਮਾਜਿਕ ਸਬੰਧਾਂ 'ਤੇ ਕੀ ਪ੍ਰਭਾਵ ਪੈਂਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਪਾਠ ਦਾ ਮੁੱਖ ਉਦੇਸ਼ ਕੀ ਹੈ? ਪਾਠਕਾਂ ਨੂੰ ਕਿਹੜਾ ਸੰਦੇਸ਼ ਦੇਣਾ ਚਾਹੁੰਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਨੁੱਖੀ ਜੀਵਨ ਵਿੱਚ ਗੁਣਾਂ ਅਤੇ ਅਵਗੁਣਾਂ ਦਾ ਸੰਤੁਲਨ ਕਿਵੇਂ ਬਣਾਇਆ ਜਾ ਸਕਦਾ ਹੈ? ਹੰਕਾਰ ਤੋਂ ਬਚਣ ਲਈ ਵਿਅਕਤੀਗਤ ਪੱਧਰ 'ਤੇ ਕੀ ਯਤਨ ਕੀਤੇ ਜਾ ਸਕਦੇ ਹਨ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੰਕਾਰ ਦੇ ਵੱਖ-ਵੱਖ ਰੂਪਾਂ ਦਾ ਵਿਸ਼ਲੇਸ਼ਣ ਕਰੋ ਅਤੇ ਦੱਸੋ ਕਿ ਇਹ ਮਨੁੱਖੀ ਵਿਕਾਸ ਵਿੱਚ ਕਿਵੇਂ ਰੁਕਾਵਟ ਬਣਦੇ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
