  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਵੈਮਾਣ ਅਤੇ ਨਿਮਰਤਾ ਇੱਕ ਦੂਜੇ ਦੇ ਪੂਰਕ ਕਿਵੇਂ ਹਨ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਦੇ ਅੰਤ ਵਿੱਚ ਦਿੱਤੇ ਗਏ ਦੋ ਸਿੱਖਣ ਨਤੀਜਿਆਂ (ਆਤਮ-ਵਿਸ਼ਵਾਸੀ ਬਣਨ ਲਈ ਪ੍ਰੇਰਿਤ ਹੋਣਾ ਅਤੇ ਹੰਕਾਰ ਤੋਂ ਪਾਸੇ ਰਹਿਣ ਦੀ ਭਾਵਨਾ ਦਾ ਵਿਕਾਸ) ਦੀ ਵਿਸਥਾਰ ਨਾਲ ਵਿਆਖਿਆ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਮਨੁੱਖੀ ਜੀਵਨ ਦੀ ਸਫਲਤਾ ਲਈ ਕਿਹੜੇ ਮੂਲ ਸਿਧਾਂਤ ਦੱਸੇ ਗਏ ਹਨ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true);
INSERT INTO public.question_bank (id, institution_id, subject_id, topic_id, grade_level_id, class_group_id, question_text, question_type, options, correct_answer, marks, difficulty_level, tags, source, created_by, is_approved, parent_question_id, sub_question_count, sequence_order) VALUES
  ('1a32f54b-b2d5-42f6-8eb6-8e6d3bb90ce4', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਨੁੱਖੀ ਜੀਵਨ ਬਹੁਤ ਹੀ ਵਿਲੱਖਣ ਹੈ। ਇਸ ਵਿੱਚ ਚਾਨਣ ਦੇ ਚਮਕਾਰੇ ਵੀ ਹਨ ਤੇ ਹਨੇਰੇ ਦੇ ਸਾਏ ਵੀ। ਇਸ ਵਿੱਚ ਕਈ ਗੁਣ ਤੇ ਅਵਗੁਣ ਹਨ। ਇਹ ਗੁਣ ਤੇ ਅਵਗੁਣ ਸਾਡੇ ਸੁਭਾਅ, ਚਾਲ-ਚਲਣ ਅਤੇ ਸ਼ਖ਼ਸੀਅਤ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰਦੇ ਹਨ। ਇਹਨਾਂ ਵਿੱਚੋਂ ਦੋ ਬਹੁਤ ਮਹੱਤਵਪੂਰਨ ਗੁਣ ਹਨ — ਹੰਕਾਰ ਅਤੇ ਸਵੈਮਾਨ। ਇਹ ਦੋਵੇਂ ਸ਼ਬਦ ਸੁਣਨ ਵਿੱਚ ਮਿਲਦੇ-ਜੁਲਦੇ ਲੱਗਦੇ ਹਨ ਪਰ ਅਸਲ ਵਿੱਚ ਇਹ ਇੱਕ-ਦੂਜੇ ਦੇ ਵਿਰੁੱਧ ਹਨ। ਹੰਕਾਰ ਮਨੁੱਖ ਨੂੰ ਪਤਨ ਵੱਲ ਲੈ ਜਾਂਦਾ ਹੈ ਜਦਕਿ ਸਵੈਮਾਨ ਮਨੁੱਖ ਨੂੰ ਬੁਲੰਦੀਆਂ ਤੱਕ ਪਹੁੰਚਾਉਂਦਾ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 10, NULL),
  ('70a6f115-8b3e-4d4f-814e-3b222eb09691', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$‘ਹੰਕਾਰ’ ਦਾ ਸ਼ਾਬਦਿਕ ਅਰਥ ਹੈ-ਆਪਣੀ ਤਾਕਤ, ਧਨ-ਦੌਲਤ, ਗਿਆਨ, ਰੂਪ, ਯੋਗਤਾ ਜਾਂ ਪਦਵੀ ਦਾ ਅਤਿ ਜ਼ਰੂਰ ਪ੍ਰਗਟਾਵਾ ਕਰਨਾ। ‘ਹੰਕਾਰ’ ਸ਼ਬਦ ਸੰਸਕ੍ਰਿਤ ਦੇ ‘ਅਹੰਕਾਰ’ ਸ਼ਬਦ ਤੋਂ ਬਣਿਆ ਹੈ। ਇਸ ਵਿੱਚ ‘ਅਹੰ’ ਦਾ ਅਰਥ ‘ਮੈਂ’ ਹੈ। ਘਮੰਡ, ਗੁਮਾਨ, ਗਰਵ, ਅਭਿਮਾਨ ਅਤੇ ਹਉਮੈ ਇਸ ਦੇ ਸਮਾਨਾਰਥੀ ਸ਼ਬਦ ਹਨ। ਜਦੋਂ ਕੋਈ ਮਨੁੱਖ ਆਪਣੀ ਸਫਲਤਾ ਜਾਂ ਤਾਕਤ ‘ਤੇ ਇਸ ਕਦਰ ਜ਼ਰੂਰ ਕਰ ਲੈਂਦਾ ਹੈ ਕਿ ਉਹ ਹੋਰਾਂ ਦੀ ਕਦਰ ਕਰਨਾ ਭੁੱਲ ਜਾਂਦਾ ਹੈ, ਤਦ ਉਸ ਵਿੱਚ ਹੰਕਾਰ ਪੈਦਾ ਹੁੰਦਾ ਹੈ। ਹੰਕਾਰੀ ਵਾਲਾ ਵਿਅਕਤੀ ਸੋਚਦਾ ਹੈ ਕਿ ਉਸ ਤੋਂ ਵੱਡਾ ਹੋਰ ਕੋਈ ਨਹੀਂ ਹੈ। ਉਹ ਆਪਣੇ ਤੋਂ ਛੋਟਿਆਂ ਨੂੰ ਅਣਦੇਖਿਆ ਕਰਦਾ ਹੈ ਅਤੇ ਵੱਡਿਆਂ ਦੀ ਸਲਾਹ ਨੂੰ ਵੀ ਟਿੱਚ ਜਾਣਦਾ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 10, NULL),
  ('298c0818-8961-43fb-9ca3-a1d3b2b0ae95', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੁਨੀਆ ਦੇ ਧਾਰਮਿਕ ਗ੍ਰੰਥਾਂ ਵਿੱਚ ਹੰਕਾਰ ਤੋਂ ਦੂਰ ਰਹਿਣ ਦੀ ਪ੍ਰੇਰਨਾ ਤੇ ਸਲਾਹ ਦਿੱਤੀ ਗਈ ਹੈ। ਗੁਰਬਾਣੀ ਵਿੱਚ ਹੰਕਾਰ ਨੂੰ ਮਨੁੱਖੀ ਸੁਭਾਅ ਦੇ ਪੰਜ ਮੁੱਖ ਵਿਕਾਰਾਂ ਵਿੱਚ ਸ਼ੁਮਾਰ ਕੀਤਾ ਗਿਆ ਹੈ। ਗੁਰਬਾਣੀ ਮਨੁੱਖ ਨੂੰ ਦੁਨਿਆਵੀ ਵਸਤਾਂ ਦਾ ਹੰਕਾਰ ਕਰਨ ਤੋਂ ਵਰਜਦੀ ਹੈ। ਇਸ ਹੰਕਾਰ ਨੂੰ ਛੱਡ ਕੇ ਪਰਉਪਕਾਰ ਦੀ ਭਾਵਨਾ ਹੀ ਮਨੁੱਖ ਨੂੰ ਸਿੱਧੇ ਰਸਤੇ ਪਾ ਸਕਦੀ ਹੈ। “ਧਨ ਭੂਮਿ ਕਾ ਜੋ ਕਰੈ ਗੁਮਾਨੁ॥ ਸੋ ਮੂਰਖੁ ਅੰਧਾ ਅਗਿਆਨੁ॥”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 10, NULL),
  ('3678c3e7-c77c-4359-b0e8-f11b461fd59e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਨੁੱਖੀ ਜੀਵਨ ਬਹੁਤ ਹੀ ਵਿਲੱਖਣ ਹੈ। ਇਸ ਵਿੱਚ ਚਾਨਣ ਦੇ ਚਮਕਾਰੇ ਵੀ ਹਨ ਤੇ ਹਨੇਰੇ ਦੇ ਸਾਏ ਵੀ। ਇਸ ਵਿੱਚ ਕਈ ਗੁਣ ਤੇ ਅਵਗੁਣ ਹਨ। ਇਹ ਗੁਣ ਤੇ ਅਵਗੁਣ ਸਾਡੇ ਸੁਭਾਅ, ਚਾਲ-ਚਲਣ ਅਤੇ ਸ਼ਖ਼ਸੀਅਤ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰਦੇ ਹਨ। ਇਹਨਾਂ ਵਿੱਚੋਂ ਦੋ ਬਹੁਤ ਮਹੱਤਵਪੂਰਨ ਗੁਣ ਹਨ — ਹੰਕਾਰ ਅਤੇ ਸਵੈਮਾਨ। ਇਹ ਦੋਵੇਂ ਸ਼ਬਦ ਸੁਣਨ ਵਿੱਚ ਮਿਲਦੇ-ਜੁਲਦੇ ਲੱਗਦੇ ਹਨ ਪਰ ਅਸਲ ਵਿੱਚ ਇਹ ਇੱਕ-ਦੂਜੇ ਦੇ ਵਿਰੁੱਧ ਹਨ। ਹੰਕਾਰ ਮਨੁੱਖ ਨੂੰ ਪਤਨ ਵੱਲ ਲੈ ਜਾਂਦਾ ਹੈ ਜਦਕਿ ਸਵੈਮਾਨ ਮਨੁੱਖ ਨੂੰ ਬੁਲੰਦੀਆਂ ਤੱਕ ਪਹੁੰਚਾਉਂਦਾ ਹੈ। ‘ਹੰਕਾਰ’ ਦਾ ਸ਼ਾਬਦਿਕ ਅਰਥ ਹੈ-ਆਪਣੀ ਤਾਕਤ, ਧਨ-ਦੌਲਤ, ਗਿਆਨ, ਰੂਪ, ਯੋਗਤਾ ਜਾਂ ਪਦਵੀ ਦਾ ਅਤਿ ਜ਼ਰੂਰ ਪ੍ਰਗਟਾਵਾ ਕਰਨਾ। ‘ਹੰਕਾਰ’ ਸ਼ਬਦ ਸੰਸਕ੍ਰਿਤ ਦੇ ‘ਅਹੰਕਾਰ’ ਸ਼ਬਦ ਤੋਂ ਬਣਿਆ ਹੈ। ਇਸ ਵਿੱਚ ‘ਅਹੰ’ ਦਾ ਅਰਥ ‘ਮੈਂ’ ਹੈ। ਘਮੰਡ, ਗੁਮਾਨ, ਗਰਵ, ਅਭਿਮਾਨ ਅਤੇ ਹਉਮੈ ਇਸ ਦੇ ਸਮਾਨਾਰਥੀ ਸ਼ਬਦ ਹਨ। ਜਦੋਂ ਕੋਈ ਮਨੁੱਖ ਆਪਣੀ ਸਫਲਤਾ ਜਾਂ ਤਾਕਤ ‘ਤੇ ਇਸ ਕਦਰ ਜ਼ਰੂਰ ਕਰ ਲੈਂਦਾ ਹੈ ਕਿ ਉਹ ਹੋਰਾਂ ਦੀ ਕਦਰ ਕਰਨਾ ਭੁੱਲ ਜਾਂਦਾ ਹੈ, ਤਦ ਉਸ ਵਿੱਚ ਹੰਕਾਰ ਪੈਦਾ ਹੁੰਦਾ ਹੈ। ਹੰਕਾਰੀ ਵਾਲਾ ਵਿਅਕਤੀ ਸੋਚਦਾ ਹੈ ਕਿ ਉਸ ਤੋਂ ਵੱਡਾ ਹੋਰ ਕੋਈ ਨਹੀਂ ਹੈ। ਉਹ ਆਪਣੇ ਤੋਂ ਛੋਟਿਆਂ ਨੂੰ ਅਣਦੇਖਿਆ ਕਰਦਾ ਹੈ ਅਤੇ ਵੱਡਿਆਂ ਦੀ ਸਲਾਹ ਨੂੰ ਵੀ ਟਿੱਚ ਜਾਣਦਾ ਹੈ। ਦੁਨੀਆ ਦੇ ਧਾਰਮਿਕ ਗ੍ਰੰਥਾਂ ਵਿੱਚ ਹੰਕਾਰ ਤੋਂ ਦੂਰ ਰਹਿਣ ਦੀ ਪ੍ਰੇਰਨਾ ਤੇ ਸਲਾਹ ਦਿੱਤੀ ਗਈ ਹੈ। ਗੁਰਬਾਣੀ ਵਿੱਚ ਹੰਕਾਰ ਨੂੰ ਮਨੁੱਖੀ ਸੁਭਾਅ ਦੇ ਪੰਜ ਮੁੱਖ ਵਿਕਾਰਾਂ ਵਿੱਚ ਸ਼ੁਮਾਰ ਕੀਤਾ ਗਿਆ ਹੈ। ਗੁਰਬਾਣੀ ਮਨੁੱਖ ਨੂੰ ਦੁਨਿਆਵੀ ਵਸਤਾਂ ਦਾ ਹੰਕਾਰ ਕਰਨ ਤੋਂ ਵਰਜਦੀ ਹੈ। ਇਸ ਹੰਕਾਰ ਨੂੰ ਛੱਡ ਕੇ ਪਰਉਪਕਾਰ ਦੀ ਭਾਵਨਾ ਹੀ ਮਨੁੱਖ ਨੂੰ ਸਿੱਧੇ ਰਸਤੇ ਪਾ ਸਕਦੀ ਹੈ। “ਧਨ ਭੂਮਿ ਕਾ ਜੋ ਕਰੈ ਗੁਮਾਨੁ॥ ਸੋ ਮੂਰਖੁ ਅੰਧਾ ਅਗਿਆਨੁ॥”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 10, NULL),
  ('411dd269-a5ac-490f-a7ca-420aaa98375f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੰਕਾਰ ਮਨੁੱਖ ਨੂੰ ਪਤਨ ਵੱਲ ਲੈ ਜਾਂਦਾ ਹੈ ਜਦਕਿ ਸਵੈਮਾਨ ਮਨੁੱਖ ਨੂੰ ਬੁਲੰਦੀਆਂ ਤੱਕ ਪਹੁੰਚਾਉਂਦਾ ਹੈ। ‘ਹੰਕਾਰ’ ਦਾ ਸ਼ਾਬਦਿਕ ਅਰਥ ਹੈ-ਆਪਣੀ ਤਾਕਤ, ਧਨ-ਦੌਲਤ, ਗਿਆਨ, ਰੂਪ, ਯੋਗਤਾ ਜਾਂ ਪਦਵੀ ਦਾ ਅਤਿ ਜ਼ਰੂਰ ਪ੍ਰਗਟਾਵਾ ਕਰਨਾ। ‘ਹੰਕਾਰ’ ਸ਼ਬਦ ਸੰਸਕ੍ਰਿਤ ਦੇ ‘ਅਹੰਕਾਰ’ ਸ਼ਬਦ ਤੋਂ ਬਣਿਆ ਹੈ। ਇਸ ਵਿੱਚ ‘ਅਹੰ’ ਦਾ ਅਰਥ ‘ਮੈਂ’ ਹੈ। ਘਮੰਡ, ਗੁਮਾਨ, ਗਰਵ, ਅਭਿਮਾਨ ਅਤੇ ਹਉਮੈ ਇਸ ਦੇ ਸਮਾਨਾਰਥੀ ਸ਼ਬਦ ਹਨ। ਜਦੋਂ ਕੋਈ ਮਨੁੱਖ ਆਪਣੀ ਸਫਲਤਾ ਜਾਂ ਤਾਕਤ ‘ਤੇ ਇਸ ਕਦਰ ਜ਼ਰੂਰ ਕਰ ਲੈਂਦਾ ਹੈ ਕਿ ਉਹ ਹੋਰਾਂ ਦੀ ਕਦਰ ਕਰਨਾ ਭੁੱਲ ਜਾਂਦਾ ਹੈ, ਤਦ ਉਸ ਵਿੱਚ ਹੰਕਾਰ ਪੈਦਾ ਹੁੰਦਾ ਹੈ। ਹੰਕਾਰੀ ਵਾਲਾ ਵਿਅਕਤੀ ਸੋਚਦਾ ਹੈ ਕਿ ਉਸ ਤੋਂ ਵੱਡਾ ਹੋਰ ਕੋਈ ਨਹੀਂ ਹੈ। ਉਹ ਆਪਣੇ ਤੋਂ ਛੋਟਿਆਂ ਨੂੰ ਅਣਦੇਖਿਆ ਕਰਦਾ ਹੈ ਅਤੇ ਵੱਡਿਆਂ ਦੀ ਸਲਾਹ ਨੂੰ ਵੀ ਟਿੱਚ ਜਾਣਦਾ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 10, NULL),
  ('5cd67716-f55e-45b1-9295-1e2dea1628e2', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੁਨੀਆ ਦੇ ਧਾਰਮਿਕ ਗ੍ਰੰਥਾਂ ਵਿੱਚ ਹੰਕਾਰ ਤੋਂ ਦੂਰ ਰਹਿਣ ਦੀ ਪ੍ਰੇਰਨਾ ਤੇ ਸਲਾਹ ਦਿੱਤੀ ਗਈ ਹੈ। ਗੁਰਬਾਣੀ ਵਿੱਚ ਹੰਕਾਰ ਨੂੰ ਮਨੁੱਖੀ ਸੁਭਾਅ ਦੇ ਪੰਜ ਮੁੱਖ ਵਿਕਾਰਾਂ ਵਿੱਚ ਸ਼ੁਮਾਰ ਕੀਤਾ ਗਿਆ ਹੈ। ਗੁਰਬਾਣੀ ਮਨੁੱਖ ਨੂੰ ਦੁਨਿਆਵੀ ਵਸਤਾਂ ਦਾ ਹੰਕਾਰ ਕਰਨ ਤੋਂ ਵਰਜਦੀ ਹੈ। ਇਸ ਹੰਕਾਰ ਨੂੰ ਛੱਡ ਕੇ ਪਰਉਪਕਾਰ ਦੀ ਭਾਵਨਾ ਹੀ ਮਨੁੱਖ ਨੂੰ ਸਿੱਧੇ ਰਸਤੇ ਪਾ ਸਕਦੀ ਹੈ। “ਧਨ ਭੂਮਿ ਕਾ ਜੋ ਕਰੈ ਗੁਮਾਨੁ॥ ਸੋ ਮੂਰਖੁ ਅੰਧਾ ਅਗਿਆਨੁ॥”$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 10, NULL),
  ('8e6f0ad4-66f4-4a4c-992f-476a9bcad51b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਵਿਦੇਸ਼ੀਆਂ ਦਾ ਰਾਜ ਸਭ ਤੋਂ ਵੱਡੀ ਸੱਟ ਸਵੈਮਾਣ ਉੱਤੇ ਹੀ ਮਾਰ ਰਿਹਾ ਸੀ। ਮਨੁੱਖ ਦੇ ਜੀਵਨ ਲਈ ਸਵੈਮਾਣ ਬਹੁਤ ਜ਼ਰੂਰੀ ਹੈ। ਜੇ ਮਨੁੱਖ ਕੋਲ ਧਨ-ਦੌਲਤ ਨਹੀਂ ਵੀ ਹੈ ਪਰ ਉਸ ਦੇ ਕੋਲ ਸਵੈਮਾਣ ਹੈ ਤਾਂ ਉਹ ਸਮਾਜ ਵਿੱਚ ਸਤਿਕਾਰ ਪਾਉਂਦਾ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6384f1c0-d915-410d-9d6e-6ee72608180b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੂਜੇ ਪਾਸੇ ਜੇ ਕਿਸੇ ਕੋਲ ਬੇਅੰਤ ਦੌਲਤ ਅਤੇ ਸ਼ਕਤੀ ਹੈ ਪਰ ਉਹ ਹੰਕਾਰੀ ਹੈ ਤਾਂ ਲੋਕ ਉਸ ਤੋਂ ਨਫ਼ਰਤ ਕਰਦੇ ਹਨ। ਹੰਕਾਰ ਕਦੇ ਵੀ ਲੰਬੇ ਸਮੇਂ ਤੱਕ ਨਹੀਂ ਟਿਕਦਾ। ਇਹ ਮਨੁੱਖ ਦੀ ਕਮਜ਼ੋਰੀ ਹੈ ਜੋ ਇੱਕ ਦਿਨ ਉਸ ਨੂੰ ਅਰਸ਼ੋਂ ਫਰਸ਼ ਉੱਤੇ ਲਿਆ ਸੁੱਟਦੀ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('cc1daae5-89da-496a-a587-3a7cd5f4427b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਵੈਮਾਣ ਮਨੁੱਖ ਦੀ ਅਸਲੀ ਸ਼ਕਤੀ ਹੈ ਜੋ ਉਸ ਦੀ ਪਛਾਣ ਬਣਦੀ ਹੈ। ਪੰਜਾਬੀ ਦੀ ਕਹਾਵਤ ਵੀ ਹੈ, 'ਹੰਕਾਰੀਆ ਸੋ ਮਾਰਿਆ'। ਸਾਡੀ ਇਤਿਹਾਸਿਕ ਅਤੇ ਧਾਰਮਿਕ ਧਰੋਹਰ ਸਾਨੂੰ ਇਹ ਸਿਖਾਉਂਦੀ ਹੈ ਕਿ ਹੰਕਾਰ ਕਰਨ ਵਾਲੇ ਮਿਟ ਗਏ ਪਰ ਸਵੈਮਾਣ ਵਾਲਿਆਂ ਦੇ ਨਾਮ ਅੱਜ ਵੀ ਸਤਿਕਾਰ ਨਾਲ ਲਏ ਜਾਂਦੇ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('69d7ff8e-2831-4b65-a8b3-0ccbfd848a38', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਾਰਿਆਂ ਨੂੰ ਸਮਝਣਾ ਚਾਹੀਦਾ ਹੈ ਕਿ ਹੰਕਾਰ ਮਨੁੱਖ ਨੂੰ ਕਦੇ ਵੀ ਲਾਭ ਨਹੀਂ ਪਹੁੰਚਾਉਂਦਾ। ਇਹ ਇੱਕ ਜ਼ਹਿਰ ਵਾਂਗ ਹੈ ਜੋ ਹੌਲੀ-ਹੌਲੀ ਮਨੁੱਖੀ ਜੀਵਨ ਨੂੰ ਖਾ ਜਾਂਦਾ ਹੈ। ਦੂਜੇ ਪਾਸੇ, ਸਵੈਮਾਣ ਜੀਵਨ ਲਈ ਉਹ ਅੰਮ੍ਰਿਤ ਹੈ ਜੋ ਮਨੁੱਖ ਨੂੰ ਸਹੀ ਰਸਤੇ ਉੱਤੇ ਲੈ ਜਾਂਦਾ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b3839ea7-4af7-44ec-90c6-683d61f96253', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਲਈ ਸਾਨੂੰ ਹਮੇਸ਼ਾ ਹੰਕਾਰ ਤੋਂ ਬਚਣਾ ਚਾਹੀਦਾ ਹੈ ਅਤੇ ਸਵੈਮਾਣ ਨੂੰ ਜੀਵਨ ਦਾ ਅਧਾਰ ਬਣਾਉਣਾ ਚਾਹੀਦਾ ਹੈ। ਅਸਲੀ ਖੁਸ਼ੀ ਅਤੇ ਅਸਲੀ ਸਫਲਤਾ ਉਹੀ ਹੈ ਜੋ ਸਵੈਮਾਣ ਨਾਲ ਮਿਲਦੀ ਹੈ। ਹੰਕਾਰ ਨਾਲ ਮਿਲੀ ਖੁਸ਼ੀ ਸਿਰਫ ਕੁਝ ਪਲਾਂ ਦੀ ਹੁੰਦੀ ਹੈ ਪਰ ਸਵੈਮਾਣ ਨਾਲ ਮਿਲਿਆ ਸਤਿਕਾਰ ਅਤੇ ਮਾਣ ਸਦੀਵੀ ਰਹਿੰਦਾ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('16216cbf-3d16-4c04-b220-5d985e17584b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੰਕਾਰ ਤੋਂ ਬਚਣ ਅਤੇ ਸਵੈਮਾਣ ਨੂੰ ਸੰਭਾਲਣ ਲਈ ਆਪਣੀ ਸਫਲਤਾ ਦੀ ਖੁਸ਼ੀ ਤਾਂ ਮਨਾਓ, ਪਰ ਕਦੇ ਗਰੂਰ ਨਾ ਕਰੋ। ਦੂਜਿਆਂ ਦੀ ਇੱਜ਼ਤ ਕਰੋ, ਚਾਹੇ ਉਹ ਤੁਹਾਡੇ ਤੋਂ ਘੱਟ ਰੁਤਬੇ ਵਾਲੇ ਹੀ ਕਿਉਂ ਨਾ ਹੋਣ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('17459d26-12d0-4914-9fe8-8e4ed448d6e7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਆਪਣੇ ਅੰਦਰ ਨਿਮਰਤਾ ਵਿਕਸਤ ਕਰੋ ਕਿਉਂਕਿ ਨਿਮਰਤਾ ਸਵੈਮਾਣ ਦੀ ਮਾਂ ਹੈ ਅਤੇ ਹੰਕਾਰ ਦੀ ਦੁਸ਼ਮਣ। ਸਫਲਤਾ ਅਤੇ ਪਦਵੀ ਨੂੰ ਆਪਣੀ ਪਛਾਣ ਨਾ ਬਣਾਓ, ਸੱਚੀ ਪਛਾਣ ਤੁਹਾਡਾ ਚਰਿੱਤਰ ਅਤੇ ਕਿਰਦਾਰ ਹੀ ਹੁੰਦੇ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('40193b40-22e6-4db2-b96d-93f81b2387ff', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਆਤਮ-ਮੰਥਨ ਕਰੋ ਅਤੇ ਰੋਜ਼ਾਨਾ ਆਪਣੇ ਵਿਹਾਰ ਨੂੰ ਨਿਰਖੋ ਕਿ ਕਿਤੇ ਹੰਕਾਰ ਤਾਂ ਨਹੀਂ ਆ ਰਿਹਾ। ਗੁਰਬਾਣੀ ਅਤੇ ਮਹਾਂਪੁਰਖਾਂ ਤੋਂ ਪ੍ਰੇਰਨਾ ਲਵੋ। ਹੰਕਾਰ ਦੀਆਂ ਕੰਧਾਂ ਉਸਾਰਨ ਦੀ ਥਾਂ ਸਵੈਮਾਣ ਦਾ ਪੁਲ ਬਣਾਓ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('cbad1274-2c8a-423a-9a05-0f6ee2447637', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਧਰੋਹਰ - ਵਿਰਾਸਤ, ਅੰਮ੍ਰਿਤ - ਜੀਵਨਦਾਇਕ ਚੀਜ਼, ਨਿਮਰਤਾ - ਨਰਮੀ, ਆਤਮ-ਮੰਥਨ - ਆਪਣੇ-ਆਪ ਨੂੰ ਜਾਣਨਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4141cce7-f32b-41b9-8575-06b6d51d1244', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦਿੱਤੀ ਪਰ ਖੁਲਾਮੀ ਸਵੀਕਾਰ ਨਾ ਕੀਤੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7494194a-e68b-433a-ae0e-86f567e1c828', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੰਕਾਰ ਕਦੇ ਵੀ ਲੰਬੇ ਸਮੇਂ ਤੱਕ ਨਹੀਂ ਟਿਕਦਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('95acf37a-a429-4943-99dd-cc4419deec6c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਵੈਮਾਣ ਮਨੁੱਖ ਦੀ ਅਸਲੀ ਸ਼ਕਤੀ ਹੈ ਜੋ ਉਸ ਦੀ ਪਛਾਣ ਬਣਦੀ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('08fa0bf2-f322-4d2f-bdd5-ee9c1306f5df', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਨੁੱਖੀ ਜੀਵਨ ਬਹੁਤ ਹੀ ਵਿਲੱਖਣ ਹੈ। ਇਸ ਵਿੱਚ ਚਾਨਣ ਦੇ ਚਮਕਾਰੇ ਵੀ ਹਨ ਤੇ ਹਨੇਰੇ ਦੇ ਸਾਏ ਵੀ। ਇਸ ਵਿੱਚ ਕਈ ਗੁਣ ਤੇ ਅਵਗੁਣ ਹਨ। ਇਹ ਗੁਣ ਤੇ ਅਵਗੁਣ ਸਾਡੇ ਸੁਭਾਅ, ਚਾਲ-ਚਲਣ ਅਤੇ ਸ਼ਖ਼ਸੀਅਤ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰਦੇ ਹਨ। ਇਹਨਾਂ ਵਿੱਚੋਂ ਦੋ ਬਹੁਤ ਮਹੱਤਵਪੂਰਨ ਗੁਣ ਹਨ — ਹੰਕਾਰ ਅਤੇ ਸਵੈਮਾਨ। ਇਹ ਦੋਵੇਂ ਸ਼ਬਦ ਸੁਣਨ ਵਿੱਚ ਮਿਲਦੇ-ਜੁਲਦੇ ਲੱਗਦੇ ਹਨ ਪਰ ਅਸਲ ਵਿੱਚ ਇਹ ਇੱਕ-ਦੂਜੇ ਦੇ ਵਿਰੁੱਧ ਹਨ। ਹੰਕਾਰ ਮਨੁੱਖ ਨੂੰ ਪਤਨ ਵੱਲ ਲੈ ਜਾਂਦਾ ਹੈ ਜਦਕਿ ਸਵੈਮਾਨ ਮਨੁੱਖ ਨੂੰ ਬੁਲੰਦੀਆਂ ਤੱਕ ਪਹੁੰਚਾਉਂਦਾ ਹੈ। ‘ਹੰਕਾਰ’ ਦਾ ਸ਼ਾਬਦਿਕ ਅਰਥ ਹੈ-ਆਪਣੀ ਤਾਕਤ, ਧਨ-ਦੌਲਤ, ਗਿਆਨ, ਰੂਪ, ਯੋਗਤਾ ਜਾਂ ਪਦਵੀ ਦਾ ਅਤਿ ਜ਼ਰੂਰ ਪ੍ਰਗਟਾਵਾ ਕਰਨਾ। ‘ਹੰਕਾਰ’ ਸ਼ਬਦ ਸੰਸਕ੍ਰਿਤ ਦੇ ‘ਅਹੰਕਾਰ’ ਸ਼ਬਦ ਤੋਂ ਬਣਿਆ ਹੈ। ਇਸ ਵਿੱਚ ‘ਅਹੰ’ ਦਾ ਅਰਥ ‘ਮੈਂ’ ਹੈ। ਘਮੰਡ, ਗੁਮਾਨ, ਗਰਵ, ਅਭਿਮਾਨ ਅਤੇ ਹਉਮੈ ਇਸ ਦੇ ਸਮਾਨਾਰਥੀ ਸ਼ਬਦ ਹਨ। ਜਦੋਂ ਕੋਈ ਮਨੁੱਖ ਆਪਣੀ ਸਫਲਤਾ ਜਾਂ ਤਾਕਤ ‘ਤੇ ਇਸ ਕਦਰ ਜ਼ਰੂਰ ਕਰ ਲੈਂਦਾ ਹੈ ਕਿ ਉਹ ਹੋਰਾਂ ਦੀ ਕਦਰ ਕਰਨਾ ਭੁੱਲ ਜਾਂਦਾ ਹੈ, ਤਦ ਉਸ ਵਿੱਚ ਹੰਕਾਰ ਪੈਦਾ ਹੁੰਦਾ ਹੈ। ਹੰਕਾਰੀ ਵਾਲਾ ਵਿਅਕਤੀ ਸੋਚਦਾ ਹੈ ਕਿ ਉਸ ਤੋਂ ਵੱਡਾ ਹੋਰ ਕੋਈ ਨਹੀਂ ਹੈ। ਉਹ ਆਪਣੇ ਤੋਂ ਛੋਟਿਆਂ ਨੂੰ ਅਣਦੇਖਿਆ ਕਰਦਾ ਹੈ ਅਤੇ ਵੱਡਿਆਂ ਦੀ ਸਲਾਹ ਨੂੰ ਵੀ ਟਿੱਚ ਜਾਣਦਾ ਹੈ। ਦੁਨੀਆ ਦੇ ਧਾਰਮਿਕ ਗ੍ਰੰਥਾਂ ਵਿੱਚ ਹੰਕਾਰ ਤੋਂ ਦੂਰ ਰਹਿਣ ਦੀ ਪ੍ਰੇਰਨਾ ਤੇ ਸਲਾਹ ਦਿੱਤੀ ਗਈ ਹੈ। ਗੁਰਬਾਣੀ ਵਿੱਚ ਹੰਕਾਰ ਨੂੰ ਮਨੁੱਖੀ ਸੁਭਾਅ ਦੇ ਪੰਜ ਮੁੱਖ ਵਿਕਾਰਾਂ ਵਿੱਚ ਸ਼ੁਮਾਰ ਕੀਤਾ ਗਿਆ ਹੈ। ਗੁਰਬਾਣੀ ਮਨੁੱਖ ਨੂੰ ਦੁਨਿਆਵੀ ਵਸਤਾਂ ਦਾ ਹੰਕਾਰ ਕਰਨ ਤੋਂ ਵਰਜਦੀ ਹੈ। ਇਸ ਹੰਕਾਰ ਨੂੰ ਛੱਡ ਕੇ ਪਰਉਪਕਾਰ ਦੀ ਭਾਵਨਾ ਹੀ ਮਨੁੱਖ ਨੂੰ ਸਿੱਧੇ ਰਸਤੇ ਪਾ ਸਕਦੀ ਹੈ। “ਧਨ ਭੂਮਿ ਕਾ ਜੋ ਕਰੈ ਗੁਮਾਨੁ॥ ਸੋ ਮੂਰਖੁ ਅੰਧਾ ਅਗਿਆਨੁ॥”$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 34, NULL),
  ('241439ac-9984-4e57-9614-889fc02664e4', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਵਿਦੇਸ਼ੀਆਂ ਦਾ ਰਾਜ ਸਭ ਤੋਂ ਵੱਡੀ ਸੱਟ ਸਵੈਮਾਣ ਉੱਤੇ ਹੀ ਮਾਰ ਰਿਹਾ ਸੀ। ਮਨੁੱਖ ਦੇ ਜੀਵਨ ਲਈ ਸਵੈਮਾਣ ਬਹੁਤ ਜ਼ਰੂਰੀ ਹੈ। ਜੇ ਮਨੁੱਖ ਕੋਲ ਧਨ-ਦੌਲਤ ਨਹੀਂ ਵੀ ਹੈ ਪਰ ਉਸ ਦੇ ਕੋਲ ਸਵੈਮਾਣ ਹੈ ਤਾਂ ਉਹ ਸਮਾਜ ਵਿੱਚ ਸਤਿਕਾਰ ਪਾਉਂਦਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8181fbbf-4aec-4b0b-8b51-a9bc9829b332', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੂਜੇ ਪਾਸੇ ਜੇ ਕਿਸੇ ਕੋਲ ਬੇਅੰਤ ਦੌਲਤ ਅਤੇ ਸ਼ਕਤੀ ਹੈ ਪਰ ਉਹ ਹੰਕਾਰੀ ਹੈ ਤਾਂ ਲੋਕ ਉਸ ਤੋਂ ਨਫ਼ਰਤ ਕਰਦੇ ਹਨ। ਹੰਕਾਰ ਕਦੇ ਵੀ ਲੰਬੇ ਸਮੇਂ ਤੱਕ ਨਹੀਂ ਟਿਕਦਾ। ਇਹ ਮਨੁੱਖ ਦੀ ਕਮਜ਼ੋਰੀ ਹੈ ਜੋ ਇੱਕ ਦਿਨ ਉਸ ਨੂੰ ਅਰਸ਼ੋਂ ਫਰਸ਼ ਉੱਤੇ ਲਿਆ ਸੁੱਟਦੀ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4a58581c-b879-432c-9bb8-daf17f3b2ac6', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਵੈਮਾਣ ਮਨੁੱਖ ਦੀ ਅਸਲੀ ਸ਼ਕਤੀ ਹੈ ਜੋ ਉਸ ਦੀ ਪਛਾਣ ਬਣਦੀ ਹੈ। ਪੰਜਾਬੀ ਦੀ ਕਹਾਵਤ ਵੀ ਹੈ, 'ਹੰਕਾਰੀਆ ਸੋ ਮਾਰਿਆ'। ਸਾਡੀ ਇਤਿਹਾਸਿਕ ਅਤੇ ਧਾਰਮਿਕ ਧਰੋਹਰ ਸਾਨੂੰ ਇਹ ਸਿਖਾਉਂਦੀ ਹੈ ਕਿ ਹੰਕਾਰ ਕਰਨ ਵਾਲੇ ਮਿਟ ਗਏ ਪਰ ਸਵੈਮਾਣ ਵਾਲਿਆਂ ਦੇ ਨਾਮ ਅੱਜ ਵੀ ਸਤਿਕਾਰ ਨਾਲ ਲਏ ਜਾਂਦੇ ਹਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a8bc27cd-1284-469c-b06b-b305ef3777bc', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਾਰਿਆਂ ਨੂੰ ਸਮਝਣਾ ਚਾਹੀਦਾ ਹੈ ਕਿ ਹੰਕਾਰ ਮਨੁੱਖ ਨੂੰ ਕਦੇ ਵੀ ਲਾਭ ਨਹੀਂ ਪਹੁੰਚਾਉਂਦਾ। ਇਹ ਇੱਕ ਜ਼ਹਿਰ ਵਾਂਗ ਹੈ ਜੋ ਹੌਲੀ-ਹੌਲੀ ਮਨੁੱਖੀ ਜੀਵਨ ਨੂੰ ਖਾ ਜਾਂਦਾ ਹੈ। ਦੂਜੇ ਪਾਸੇ, ਸਵੈਮਾਣ ਜੀਵਨ ਲਈ ਉਹ ਅੰਮ੍ਰਿਤ ਹੈ ਜੋ ਮਨੁੱਖ ਨੂੰ ਸਹੀ ਰਸਤੇ ਉੱਤੇ ਲੈ ਜਾਂਦਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('125aaf2c-2191-4088-aa1d-45a6e78ac457', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਲਈ ਸਾਨੂੰ ਹਮੇਸ਼ਾ ਹੰਕਾਰ ਤੋਂ ਬਚਣਾ ਚਾਹੀਦਾ ਹੈ ਅਤੇ ਸਵੈਮਾਣ ਨੂੰ ਜੀਵਨ ਦਾ ਅਧਾਰ ਬਣਾਉਣਾ ਚਾਹੀਦਾ ਹੈ। ਅਸਲੀ ਖੁਸ਼ੀ ਅਤੇ ਅਸਲੀ ਸਫਲਤਾ ਉਹੀ ਹੈ ਜੋ ਸਵੈਮਾਣ ਨਾਲ ਮਿਲਦੀ ਹੈ। ਹੰਕਾਰ ਨਾਲ ਮਿਲੀ ਖੁਸ਼ੀ ਸਿਰਫ ਕੁਝ ਪਲਾਂ ਦੀ ਹੁੰਦੀ ਹੈ ਪਰ ਸਵੈਮਾਣ ਨਾਲ ਮਿਲਿਆ ਸਤਿਕਾਰ ਅਤੇ ਮਾਣ ਸਦੀਵੀ ਰਹਿੰਦਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('cfef4421-88bd-4b2b-a100-7b1f018df0f6', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੰਕਾਰ ਤੋਂ ਬਚਣ ਅਤੇ ਸਵੈਮਾਣ ਨੂੰ ਸੰਭਾਲਣ ਲਈ ਆਪਣੀ ਸਫਲਤਾ ਦੀ ਖੁਸ਼ੀ ਤਾਂ ਮਨਾਓ, ਪਰ ਕਦੇ ਗਰੂਰ ਨਾ ਕਰੋ। ਦੂਜਿਆਂ ਦੀ ਇੱਜ਼ਤ ਕਰੋ, ਚਾਹੇ ਉਹ ਤੁਹਾਡੇ ਤੋਂ ਘੱਟ ਰੁਤਬੇ ਵਾਲੇ ਹੀ ਕਿਉਂ ਨਾ ਹੋਣ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b7737246-b0f7-42fc-8bcc-f843ec099300', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਆਪਣੇ ਅੰਦਰ ਨਿਮਰਤਾ ਵਿਕਸਤ ਕਰੋ ਕਿਉਂਕਿ ਨਿਮਰਤਾ ਸਵੈਮਾਣ ਦੀ ਮਾਂ ਹੈ ਅਤੇ ਹੰਕਾਰ ਦੀ ਦੁਸ਼ਮਣ। ਸਫਲਤਾ ਅਤੇ ਪਦਵੀ ਨੂੰ ਆਪਣੀ ਪਛਾਣ ਨਾ ਬਣਾਓ, ਸੱਚੀ ਪਛਾਣ ਤੁਹਾਡਾ ਚਰਿੱਤਰ ਅਤੇ ਕਿਰਦਾਰ ਹੀ ਹੁੰਦੇ ਹਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c6471b13-6eb0-42e6-8c54-bdf0fc53404d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਆਤਮ-ਮੰਥਨ ਕਰੋ ਅਤੇ ਰੋਜ਼ਾਨਾ ਆਪਣੇ ਵਿਹਾਰ ਨੂੰ ਨਿਰਖੋ ਕਿ ਕਿਤੇ ਹੰਕਾਰ ਤਾਂ ਨਹੀਂ ਆ ਰਿਹਾ। ਗੁਰਬਾਣੀ ਅਤੇ ਮਹਾਂਪੁਰਖਾਂ ਤੋਂ ਪ੍ਰੇਰਨਾ ਲਵੋ। ਹੰਕਾਰ ਦੀਆਂ ਕੰਧਾਂ ਉਸਾਰਨ ਦੀ ਥਾਂ ਸਵੈਮਾਣ ਦਾ ਪੁਲ ਬਣਾਓ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('884c25f1-79e0-45f5-b1a7-38d3118db272', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '127cfa18-e60f-407b-89ef-366a84d1430d', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਧਰੋਹਰ - ਵਿਰਾਸਤ, ਅੰਮ੍ਰਿਤ - ਜੀਵਨਦਾਇਕ ਚੀਜ਼, ਨਿਮਰਤਾ - ਨਰਮੀ, ਆਤਮ-ਮੰਥਨ - ਆਪਣੇ-ਆਪ ਨੂੰ ਜਾਣਨਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-54-921Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
